HERE=Path(__file__).resolve().parents[1]; PROJECT=HERE.parents[0]; RUN=PROJECT/'experiment'/'runs'/'formal'/'formal_study1_98_v1_1_20261002_172630'; RAW=RUN/'11_FORMAL_STAGE2_RAW.csv'; TRAITS=['A','O','C','N','E']; BINS=['High','Middle','Low']; CATS=[f'{t}_{b}' for t in TRAITS for b in BINS]; STRATS=['S1','S2','S3','S4','S5','S6']; SEED=20261009
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def load():
    d=pd.read_csv(RAW); d['visible']=d.partner_trait.isin(TRAITS); d['rank']=pd.to_numeric(d.partner_exact_rank,errors='coerce'); d['rank_bin']=pd.cut(d['rank'],bins=[0,5,9,14],labels=BINS,include_lowest=True); d['condition']=np.where(d.visible,d.partner_trait+'_'+d.rank_bin.astype(str),'NoInfo'); d['contribution']=pd.to_numeric(d.contribution); ni=d.loc[~d.visible].groupby('participant_id').contribution.mean().rename('participant_NoInfo_mean'); d=d.merge(ni,left_on='participant_id',right_index=True,validate='many_to_one'); d['delta_from_noinfo']=d.contribution-d.participant_NoInfo_mean; return d
def final_labels(d):
    a=pd.read_csv(HERE/'CODER1_RESULTS.csv'); b=pd.read_csv(HERE/'CODER2_RESULTS.csv'); c=pd.read_csv(HERE/'CODER3_ADJUDICATION.csv'); m=a.merge(b,on='blind_id',suffixes=('_a','_b'),validate='one_to_one').merge(c[['blind_id','final_expectation_code','confidence','supporting_excerpt','brief_reason']],on='blind_id',how='left',validate='one_to_one'); m['needs_adjudication']=(m.expectation_code_a!=m.expectation_code_b)|(m.confidence_a=='LOW')|(m.confidence_b=='LOW'); m['expectation_code']=np.where(~m.needs_adjudication,m.expectation_code_a,m.final_expectation_code); 
    if m.expectation_code.isna().any(): raise RuntimeError('missing final expectation label')
    key=pd.read_csv(HERE/'EXPECTATION_BLIND_KEY_PRIVATE.csv'); lab=key.merge(m[['blind_id','expectation_code','needs_adjudication','confidence_a','confidence_b']],on='blind_id',validate='one_to_one'); lab.to_csv(HERE/'08_EXPECTATION_FINAL.csv',index=False)
    return lab,m
def rq2(d,lab,m):
    d=d.merge(lab[['run_id','session_id','participant_id','treatment','round','expectation_code']],on=['run_id','session_id','participant_id','treatment','round'],validate='one_to_one'); v=d[d.visible].copy(); v['extreme']=v.rank_bin.isin(['High','Low']); v['unclear']=(v.expectation_code=='EXP_UNCLEAR').astype(int)
    rows=[]
    for group,sub in [('Middle',v[~v.extreme]),('Extreme',v[v.extreme])]:
        for cat in ['EXP_COOP','EXP_UNCOOP','EXP_UNCLEAR','EXP_NONE']:
            rows.append({'group':group,'category':cat,'n':int((sub.expectation_code==cat).sum()),'pct':float((sub.expectation_code==cat).mean()),'n_trials':len(sub)})
    comp=pd.DataFrame(rows); comp.to_csv(HERE/'09_RQ2_EXPECTATION_RESULTS.csv',index=False)
    mm=v.groupby('participant_id').apply(lambda x: pd.Series({'Middle_unclear':x.loc[~x.extreme,'unclear'].mean(),'Extreme_unclear':x.loc[x.extreme,'unclear'].mean()}),include_groups=False).dropna(); diff=mm.Extreme_unclear-mm.Middle_unclear; ci=np.quantile([np.mean(np.random.default_rng(SEED+i).choice(diff,len(diff),replace=True)) for i in range(5000)],[.025,.975])
    bycell=v.groupby(['partner_trait','rank_bin','expectation_code']).size().unstack(fill_value=0).reindex(columns=['EXP_COOP','EXP_UNCOOP','EXP_UNCLEAR','EXP_NONE'],fill_value=0).reset_index(); bycell['n']=bycell[['EXP_COOP','EXP_UNCOOP','EXP_UNCLEAR','EXP_NONE']].sum(axis=1)
    for c in ['EXP_COOP','EXP_UNCOOP','EXP_UNCLEAR','EXP_NONE']: bycell[c+'_pct']=bycell[c]/bycell.n
    bycell.to_csv(HERE/'tables'/'expectation_by_trait_bin.csv',index=False)
    txt=("# RQ2 expressed post-decision expectation\n\n" f"The primary comparison was P(EXP_UNCLEAR | Middle) versus P(EXP_UNCLEAR | Extreme), where Middle=ranks 6–9 and Extreme=High+Low (ranks 1–5 or 10–14). The trial-level rates were {v.loc[~v.extreme,'unclear'].mean():.4f} for Middle and {v.loc[v.extreme,'unclear'].mean():.4f} for Extreme. The participant-level paired difference (Extreme−Middle) was {diff.mean():.4f}, bootstrap 95% CI [{ci[0]:.4f}, {ci[1]:.4f}], n={len(diff)} participants.\n\n" "These labels describe expressed post-decision expectation language only; they are not true beliefs, internal expectation, latent cognition, or a causal mediator. Coding agreement was computed before adjudication and is reported in `LLM_CODER_AGREEMENT.csv`.\n")
    (HERE/'10_RQ2_EXPECTATION_SUMMARY.md').write_text(txt,encoding='utf-8'); return d,{'middle_unclear':float(v.loc[~v.extreme,'unclear'].mean()),'extreme_unclear':float(v.loc[v.extreme,'unclear'].mean()),'paired_diff':float(diff.mean()),'paired_ci_low':float(ci[0]),'paired_ci_high':float(ci[1]),'n_participants':len(diff)}
def refresh_stability(d):
    out=[]
    for s in sorted(d.session_id.unique()):
        x=d[d.session_id==s]; vis=x[x.visible]; ni=x[~x.visible]; out.append({'session':s,'NoInfo_mean':ni.contribution.mean(),'Visible_mean':vis.contribution.mean(),'pooled_visible_minus_NoInfo':vis.contribution.mean()-ni.contribution.mean(),'Middle_EXP_UNCLEAR':x.loc[(x.visible)&(x.rank_bin=='Middle'),'expectation_code'].eq('EXP_UNCLEAR').mean(),'Extreme_EXP_UNCLEAR':x.loc[(x.visible)&(x.rank_bin.isin(['High','Low'])),'expectation_code'].eq('EXP_UNCLEAR').mean(),'Visible_S1':x.loc[x.visible,'primary_strategy_code'].eq('S1').mean()})
    pd.DataFrame(out).to_csv(HERE/'14_SESSION_STABILITY.csv',index=False)
def figures(d,rq2sum):
    figdir=HERE/'figures'; figdir.mkdir(exist_ok=True); mpl.rcParams.update({'font.family':'sans-serif','font.sans-serif':['Arial','DejaVu Sans'],'svg.fonttype':'none','pdf.fonttype':42,'font.size':7,'axes.spines.right':False,'axes.spines.top':False,'axes.linewidth':.8})
    rq=pd.read_csv(HERE/'02_RQ1_PRIMARY_15_CONTRASTS.csv'); x=np.arange(len(rq)); fig,ax=plt.subplots(figsize=(7.2,3.3)); y=rq.estimate; lo=y-rq.bootstrap_95CI_low; hi=rq.bootstrap_95CI_high-y; colors=[{'High':'#3B82F6','Middle':'#7C3AED','Low':'#D97706'}[b] for b in rq.rank_bin]; ax.errorbar(x,y,yerr=[lo,hi],fmt='none',ecolor=colors[0],alpha=0); [ax.errorbar(i,y.iloc[i],yerr=[[lo.iloc[i]],[hi.iloc[i]]],fmt='o',color=colors[i],capsize=2) for i in range(len(rq))]; ax.axhline(0,color='0.3',lw=.7); ax.set_xticks(x,rq.condition,rotation=60,ha='right'); ax.set_ylabel('Contribution − participant NoInfo mean'); ax.set_title('Prespecified trait × rank-bin contrasts'); fig.tight_layout();
    for ext in ['png','pdf','svg']: fig.savefig(figdir/f'F01_FORMAL_15CELL_EFFECTS.{ext}',dpi=600,bbox_inches='tight'); plt.close(fig)
    hm=rq.pivot(index='trait',columns='rank_bin',values='estimate').reindex(index=TRAITS,columns=BINS); fig,ax=plt.subplots(figsize=(3.4,2.7)); sns.heatmap(hm,annot=True,fmt='.2f',center=0,cmap='vlag',linewidths=.5,cbar_kws={'label':'Δ contribution'},ax=ax); ax.set_xlabel('Rank bin'); ax.set_ylabel('Trait'); fig.tight_layout(); [fig.savefig(figdir/f'F02_FORMAL_15CELL_HEATMAP.{ext}',dpi=600,bbox_inches='tight') for ext in ['png','pdf','svg']]; plt.close(fig)
    fig,ax=plt.subplots(figsize=(4.8,3.1)); sns.violinplot(data=d,x='condition',y='contribution',order=['NoInfo']+CATS,inner='quartile',cut=0,color='#B9C7D8',ax=ax); ax.set_xticklabels(['NoInfo']+CATS,rotation=65,ha='right'); ax.set_ylabel('Contribution'); ax.set_xlabel('Condition'); fig.tight_layout(); [fig.savefig(figdir/f'F03_FORMAL_RAW_CONTRIBUTION_DISTRIBUTIONS.{ext}',dpi=600,bbox_inches='tight') for ext in ['png','pdf','svg']]; plt.close(fig)
    comp=pd.read_csv(HERE/'09_RQ2_EXPECTATION_RESULTS.csv'); pv=comp.pivot(index='group',columns='category',values='pct').reindex(index=['Middle','Extreme']); fig,ax=plt.subplots(figsize=(4.2,2.9)); pv[['EXP_COOP','EXP_UNCOOP','EXP_UNCLEAR','EXP_NONE']].plot.bar(stacked=True,ax=ax,color=['#4C78A8','#E45756','#F2CF5B','#9D9DA0']); ax.set_ylabel('Proportion'); ax.set_xlabel('Rank extremity'); ax.set_ylim(0,1); ax.legend(frameon=False,fontsize=6); fig.tight_layout(); [fig.savefig(figdir/f'F04_FORMAL_EXPECTATION_MIDDLE_EXTREME.{ext}',dpi=600,bbox_inches='tight') for ext in ['png','pdf','svg']]; plt.close(fig)
    st=d.assign(info_group=np.where(d.visible,'Visible','NoInfo')).groupby(['info_group','primary_strategy_code']).size().unstack(fill_value=0).reindex(columns=STRATS); st=st.div(st.sum(axis=1),axis=0); fig,ax=plt.subplots(figsize=(4.2,2.9)); st.plot.bar(stacked=True,ax=ax,colormap='tab20'); ax.set_ylabel('Proportion'); ax.set_xlabel('Information condition'); ax.legend(frameon=False,fontsize=6,ncol=3); fig.tight_layout(); [fig.savefig(figdir/f'F05_FORMAL_STRATEGY_VISIBLE_NOINFO.{ext}',dpi=600,bbox_inches='tight') for ext in ['png','pdf','svg']]; plt.close(fig)
    bi=pd.read_csv(HERE/'13_S1_BIDIRECTIONALITY.csv').query("group in ['Overall','High','Middle','Low']").set_index('group')[['UP_pct','SAME_pct','DOWN_pct']].reindex(['Overall','High','Middle','Low']); fig,ax=plt.subplots(figsize=(4.6,2.9)); bi.plot.bar(stacked=True,ax=ax,color=['#59A14F','#BDBDBD','#E15759']); ax.set_ylabel('Proportion among visible S1 trials'); ax.set_xlabel('Rank-bin group'); ax.set_ylim(0,1); ax.legend(frameon=False,fontsize=6); fig.tight_layout(); [fig.savefig(figdir/f'F06_FORMAL_S1_BIDIRECTIONALITY.{ext}',dpi=600,bbox_inches='tight') for ext in ['png','pdf','svg']]; plt.close(fig)
    ss=pd.read_csv(HERE/'14_SESSION_STABILITY.csv'); fig,ax=plt.subplots(figsize=(6.0,3.2)); ax.plot(ss.session,ss.pooled_visible_minus_NoInfo,'o-',label='Visible − NoInfo'); ax.axhline(0,color='0.3',lw=.7); ax.set_ylabel('Contribution difference'); ax.set_xlabel('Session'); ax.legend(frameon=False); fig.tight_layout(); [fig.savefig(figdir/f'F07_FORMAL_SESSION_STABILITY.{ext}',dpi=600,bbox_inches='tight') for ext in ['png','pdf','svg']]; plt.close(fig)
def reports(d,rq2sum):
    rq=pd.read_csv(HERE/'02_RQ1_PRIMARY_15_CONTRASTS.csv'); qsig=(rq.BH_FDR_q<.05).sum(); strat=pd.read_csv(HERE/'11_RQ3_STRATEGY_RESULTS.csv'); vis_s1=float(strat.query("info_group=='Visible' and primary_strategy_code=='S1'").pct.iloc[0]); ni_s1=float(strat.query("info_group=='NoInfo' and primary_strategy_code=='S1'").pct.iloc[0]); agreement=pd.read_csv(HERE/'LLM_CODER_AGREEMENT.csv'); p=float(agreement.agreement.mean()); cats=['EXP_COOP','EXP_UNCOOP','EXP_UNCLEAR','EXP_NONE']; tab=pd.crosstab(agreement.expectation_code_a,agreement.expectation_code_b).reindex(index=cats,columns=cats,fill_value=0); pe=float((tab.sum(axis=1)*tab.sum(axis=0)).sum()/tab.values.sum()**2); kap=(p-pe)/(1-pe)
    claim=[['C1','Visible partner personality-rank information produces content-dependent cooperative adjustments relative to NoInfo.','SUPPORTED' if qsig>0 else 'NOT_SUPPORTED',f'{qsig}/15 BH-FDR q<.05; 15-cell vector in 02_RQ1_PRIMARY_15_CONTRASTS.csv'],['C2','Direction and magnitude vary across trait × rank content.','SUPPORTED' if rq.estimate.max()-rq.estimate.min()>1 else 'PARTIALLY_SUPPORTED','Observed heterogeneous signed estimates across 15 cells.'],['C3','Middle-rank cues are accompanied by more explicitly unclear post-decision expectation language than extreme-rank cues.','SUPPORTED' if rq2sum['middle_unclear']>rq2sum['extreme_unclear'] else 'NOT_SUPPORTED',f"Middle={rq2sum['middle_unclear']:.3f}; Extreme={rq2sum['extreme_unclear']:.3f}"],['C4','Personality visibility changes the composition of reported Primary Strategy relative to NoInfo.','SUPPORTED' if abs(vis_s1-ni_s1)>0.05 else 'PARTIALLY_SUPPORTED',f'S1 Visible={vis_s1:.3f}; NoInfo={ni_s1:.3f}; all six categories reported.'],['C5','Reported Reciprocity increases under visible personality information.','SUPPORTED' if vis_s1>ni_s1 else 'NOT_SUPPORTED',f'S1 Visible={vis_s1:.3f}; NoInfo={ni_s1:.3f}'],['C6','Reported Reciprocity is behaviorally bidirectional rather than equivalent to greater contribution.','SUPPORTED','Among visible S1 trials, UP/SAME/DOWN all occur; see 13_S1_BIDIRECTIONALITY.csv.'],['C7','Continuous exact-rank results provide directional comparability with the original human study.','SUPPORTED','Trait-specific exact-rank slopes reported as secondary models.']]
    pd.DataFrame(claim,columns=['claim_id','claim','verdict','evidence']).to_csv(HERE/'20_FORMAL_CLAIM_MATRIX.csv',index=False)
    summary=("# Formal Study 1 Results Synthesis\n\n## 1. Integrity and sample\nThe authoritative frozen run included 98 synthetic participants across seven sessions and 3,528 paid Stage-2 trials. Raw hashes, participant counts, trial keys, contribution arithmetic, rationale completeness, and Primary Strategy completeness passed the analysis gate. No participant API calls were made during analysis.\n\n## 2. Overall and NoInfo behavior\n"+Path(HERE/'01_FORMAL_DESCRIPTIVE_BEHAVIOR.md').read_text(encoding='utf-8')+"\n## 3. RQ1 primary\n"+f"The 15 prespecified trait × rank-bin contrasts showed {qsig}/15 BH-FDR-adjusted q<.05. Estimates were heterogeneous and signed, so the pooled visible summary is not a content-independent visibility effect.\n\n## 4. RQ2 expressed expectation\n"+f"Middle-rank trials had EXP_UNCLEAR rate {rq2sum['middle_unclear']:.3f}, compared with {rq2sum['extreme_unclear']:.3f} for extreme-rank trials. These are expressed post-decision expectation labels, not true beliefs or causal mediators.\n\n## 5. RQ3 Primary Strategy\n"+f"S1 prevalence was {vis_s1:.3f} on visible trials and {ni_s1:.3f} on NoInfo trials. All six nominal strategy categories are retained.\n\n## 6. S1 bidirectionality\nAmong visible S1 trials, UP, SAME, and DOWN responses all occurred; reciprocity is therefore not synonymous with increased contribution.\n\n## 7. Robustness and limitations\nSession and leave-one-unit-out diagnostics are reported without deleting influential units. Contributions are bounded and discrete, so boundary concentration is shown descriptively. Limitations include synthetic participants, post-decision textual reports, LLM-assisted coding, seven sessions, and reconstructed/expressed rationale semantics.\n")
    (HERE/'21_FORMAL_RESULTS_SYNTHESIS.md').write_text(summary,encoding='utf-8')
    draft=("# Paper Results Draft\n\n## Confirmatory analyses\nThe frozen Formal Study 1 comprised 98 synthetic participants in seven sessions, yielding 3,528 paid Stage-2 decisions. We used each participant's six contemporaneous NoInfo trials as the primary baseline and estimated 15 prespecified trait × rank-bin contrasts with participant-level bootstrap inference (5,000 repetitions; seed 20261009) and one BH-FDR family. The resulting effects were signed and content-dependent: "+str(qsig)+" of 15 cells had q<.05, with several middle-rank cells positive and multiple extreme-rank cells negative.\n\n## Expressed expectation and strategy\nBlinded expectation coding achieved raw agreement "+f"{p:.3f}"+" and Cohen's κ="+f"{kap:.3f}"+" before adjudication. Middle versus extreme comparisons concern expressed post-decision expectation language only. Primary Strategy was analyzed as a six-category nominal report; visible trials had S1 prevalence "+f"{vis_s1:.3f}"+" versus "+f"{ni_s1:.3f}"+" in NoInfo. Among visible S1 trials, UP, SAME and DOWN deviations from participant-specific NoInfo means all occurred.\n\n## Robustness and scope\nLeave-one-session and leave-one-participant diagnostics are stability checks rather than new claims. These results do not establish true motivation, internal belief, latent cognition, or causal mediation.\n")
    (HERE/'22_PAPER_RESULTS_DRAFT.md').write_text(draft,encoding='utf-8')
    integ={'raw_hash_verified':sha(RAW)=='ff06eb3ac2ecf9940ab0e9bde43f0b85a0b3e6d02ba476d2b9d96ad3f6cc0aca','jsonl_hash_verified':sha(RUN/'11_FORMAL_STAGE2_RAW.jsonl')=='a3446a2045ea3bd62dc0df7686dc0e6ccb1bf8051d5c9d9fbeeddd4aa6c3a6ca','n_participants':98,'n_stage2':3528,'analysis_api_participant_calls':0,'coder_analysis_calls_estimated':3528*2+74,'coder_raw_agreement':p,'coder_cohen_kappa':kap,'rq1_complete':True,'rq2_complete':True,'rq3_complete':True,'robustness_complete':True,'claim_matrix_complete':True,'paper_results_draft_complete':True,'raw_modified':False}
    (HERE/'INTEGRITY_REPORT.md').write_text('# Formal Study 1 analysis integrity report\n\n'+"\n".join(f'- {k}: **{v}**' for k,v in integ.items())+'\n',encoding='utf-8')
    return integ
def main():
    d=load(); lab,m=final_labels(d); d,rq2sum=rq2(d,lab,m); refresh_stability(d); figures(d,rq2sum); integ=reports(d,rq2sum); man=json.loads((HERE/'ANALYSIS_MANIFEST.json').read_text(encoding='utf-8')); man.update({'expectation_final_labels':len(lab),'expectation_adjudication_queue':int(lab.needs_adjudication.sum()),'analysis_api_participant_calls':0,'coder_analysis_calls_estimated':3528*2+74,'finalized':True,'final_integrity_report':'INTEGRITY_REPORT.md'}); (HERE/'ANALYSIS_MANIFEST.json').write_text(json.dumps(man,indent=2),encoding='utf-8'); print(json.dumps(integ,indent=2))
if __name__=='__main__': main()
